package com.loopers.interfaces.api.payment
import com.loopers.domain.payment.PaymentGateway;import com.loopers.infrastructure.payment.PgSimulatorPaymentGateway;import org.assertj.core.api.Assertions.assertThat;import org.junit.jupiter.api.Test
class PgSimulatorContractTest{@Test fun stringOrderIdAndBothLookupRoutesAreCompatible(){val pg=PgSimulatorPaymentGateway();var created:PaymentGateway.Result?=null;for(i in 1..5)if(created==null)try{val order="LP-SMOKE-%02d".format(i);created=pg.create("135135",PaymentGateway.Request(order,"SAMSUNG","1234-1234-1234-1234",1000,"http://localhost:8080/callback"))}catch(_:RuntimeException){};val result=created;assertThat(result).describedAs("one of five bounded POSTs must reach the simulator").isNotNull();result!!;assertThat(result.orderId).startsWith("LP-SMOKE-");assertThat(pg.findByTransactionKey("135135",result.transactionKey).transactionKey).isEqualTo(result.transactionKey);assertThat(pg.findByOrderId("135135",result.orderId)).isNotEmpty()}}
